import (
    "fmt"
    "sync"
)

// Node represents a doubly linked list node storing key-value pairs.
type Node struct {
    key   string
    value interface{}
    prev  *Node
    next  *Node
}

// LRUCache implements a thread-safe O(1) LRU eviction cache.
type LRUCache struct {
    mu       sync.Mutex
    capacity int
    cache    map[string]*Node
    head     *Node // Dummy head
    tail     *Node // Dummy tail
}

// NewLRUCache initializes and returns an LRUCache.
func NewLRUCache(capacity int) *LRUCache {
    c := &LRUCache{
        capacity: capacity,
        cache:    make(map[string]*Node),
        head:     &Node{},
        tail:     &Node{},
    }
    c.head.next = c.tail
    c.tail.prev = c.head
    return c
}

// remove unlinks a node from its current position in the list.
func (c *LRUCache) remove(node *Node) {
    node.prev.next = node.next
    node.next.prev = node.prev
}

// addToHead links a node immediately after the dummy head node.
func (c *LRUCache) addToHead(node *Node) {
    node.next = c.head.next
    node.prev = c.head
    c.head.next.prev = node
    c.head.next = node
}

// Get retrieves a key, promotes it to MRU (head), and returns the value.
func (c *LRUCache) Get(key string) (interface{}, bool) {
    c.mu.Lock()
    defer c.mu.Unlock()

    node, exists := c.cache[key]
    if !exists {
        return nil, false
    }

    c.remove(node)
    c.addToHead(node)
    return node.value, true
}

// Put adds or updates a key-value pair, evicting the LRU tail if capacity is exceeded.
func (c *LRUCache) Put(key string, value interface{}) {
    c.mu.Lock()
    defer c.mu.Unlock()

    node, exists := c.cache[key]
    if exists {
        node.value = value
        c.remove(node)
        c.addToHead(node)
        return
    }

    newNode := &Node{key: key, value: value}
    c.cache[key] = newNode
    c.addToHead(newNode)

    if len(c.cache) > c.capacity {
        // Evict the least recently used node (immediately preceding dummy tail)
        victim := c.tail.prev
        c.remove(victim)
        delete(c.cache, victim.key)
    }
}

func main() {
    cache := NewLRUCache(3)

    cache.Put("a", 1)
    cache.Put("b", 2)
    cache.Put("c", 3)

    fmt.Println("Initial Cache State:")
    printCache(cache)

    // Access "a" to promote it to the most recently used (MRU) position
    val, found := cache.Get("a")
    fmt.Printf("\nAccessed key 'a' (value: %v, found: %t)\n", val, found)
    printCache(cache)

    // Insert "d" to trigger eviction of the tail node (which is now 'b')
    fmt.Println("\nInserting key 'd' (exceeding capacity of 3):")
    cache.Put("d", 4)
    printCache(cache)
}

func printCache(c *LRUCache) {
    c.mu.Lock()
    defer c.mu.Unlock()
    curr := c.head.next
    fmt.Print("Head (MRU) -> ")
    for curr != c.tail {
        fmt.Printf("[%s: %v] -> ", curr.key, curr.value)
        curr = curr.next
    }
    fmt.Println("Tail (LRU)")
}

async function getUser(id: string): Promise<User> {
  // 1. Check cache
  const cached = await redis.get(`user:${id}`);
  if (cached) return JSON.parse(cached);

  // 2. Cache miss - fetch from DB
  const user = await db.users.findUnique({ where: { id } });
  if (!user) throw new NotFoundError();

  // 3. Populate cache with TTL
  await redis.setex(`user:${id}`, 3600, JSON.stringify(user));
  return user;
}

// Invalidate on write
async function updateUser(id: string, data: Partial<User>) {
  await db.users.update({ where: { id }, data });
  await redis.del(`user:${id}`);  // bust cache
}

func GetUser(ctx context.Context, id string) (*User, error) {
    // Check cache
    cached, err := rdb.Get(ctx, "user:"+id).Result()
    if err == nil {
        var u User
        json.Unmarshal([]byte(cached), &u)
        return &u, nil
    }

    // Cache miss
    u, err := db.QueryUser(ctx, id)
    if err != nil {
        return nil, err
    }

    // Populate cache (1 hour TTL)
    data, _ := json.Marshal(u)
    rdb.Set(ctx, "user:"+id, data, time.Hour)
    return u, nil
}

import redis
import json
from functools import wraps

r = redis.Redis()

def cached(ttl=3600):
    def decorator(fn):
        @wraps(fn)
        def wrapper(*args, **kwargs):
            key = f"{fn.__name__}:{args}:{kwargs}"
            hit = r.get(key)
            if hit:
                return json.loads(hit)
            result = fn(*args, **kwargs)
            r.setex(key, ttl, json.dumps(result))
            return result
        return wrapper
    return decorator

@cached(ttl=1800)
def get_user(user_id):
    return db.query("SELECT * FROM users WHERE id=%s", user_id)

