import (
    "errors"
    "fmt"
)

type Node struct {
    ID          int
    Data        map[string]string
    Peers       map[int]*Node
    Partitioned bool
}

type Cluster struct {
    Nodes map[int]*Node
}

func NewCluster() *Cluster {
    c := &Cluster{Nodes: make(map[int]*Node)}
    for i := 1; i <= 3; i++ {
        c.Nodes[i] = &Node{
            ID:    i,
            Data:  make(map[string]string),
            Peers: make(map[int]*Node),
        }
    }
    // Connect peers
    for i, n := range c.Nodes {
        for j, peer := range c.Nodes {
            if i != j {
                n.Peers[j] = peer
            }
        }
    }
    return c
}

// Simulates a network partition separating Node 3 from Nodes 1 and 2
func (c *Cluster) PartitionNode3() {
    c.Nodes[3].Partitioned = true
    // Mark peers on Node 3 as partitioned
    for _, peer := range c.Nodes[3].Peers {
        peer.Partitioned = true
    }
}

// AP Write: Accepts write locally on node, returns success immediately
func (n *Node) WriteAP(key, value string) error {
    n.Data[key] = value
    fmt.Printf("[AP Mode] Node %d accepted local write: %s=%s\n", n.ID, key, value)
    return nil
}

// CP Write: Requires quorum (W > N/2) across reachable peers before succeeding
func (n *Node) WriteCP(key, value string) error {
    nodesTotal := len(n.Peers) + 1
    quorumNeeded := (nodesTotal / 2) + 1
    successfulWrites := 1 // write locally first

    n.Data[key] = value

    for id, peer := range n.Peers {
        // If node or target peer is partitioned, replicate write fails
        if n.Partitioned || peer.Partitioned {
            fmt.Printf("[CP Mode] Node %d failed to replicate write to Node %d (partitioned)\n", n.ID, id)
            continue
        }
        peer.Data[key] = value
        successfulWrites++
    }

    if successfulWrites < quorumNeeded {
        // Rollback local change if quorum fails
        delete(n.Data, key)
        return errors.New("write failed: quorum unreachable due to network partition")
    }

    fmt.Printf("[CP Mode] Node %d achieved quorum write (%d/%d instances verified)\n", n.ID, successfulWrites, quorumNeeded)
    return nil
}

func main() {
    // Initialize a 3-node cluster
    cluster := NewCluster()

    fmt.Println("--- Normal Operation (No Partition) ---")
    // CP write succeeds because all nodes are reachable (3/3 nodes succeed)
    err := cluster.Nodes[3].WriteCP("key1", "val1")
    fmt.Printf("CP Write result: %v\n\n", err)

    fmt.Println("--- Network Partition: Node 3 Isolated ---")
    cluster.PartitionNode3()

    // AP Write succeeds on Node 3 despite being partitioned
    err = cluster.Nodes[3].WriteAP("key2", "val2")
    fmt.Printf("AP Write result: %v\n\n", err)

    // CP Write fails on Node 3 because it cannot reach quorum
    err = cluster.Nodes[3].WriteCP("key3", "val3")
    fmt.Printf("CP Write result: %v\n", err)
}

interface Env {
  ORIGIN_URL: string;
}

export default {
  async fetch(
    request: Request,
    env: Env,
    ctx: ExecutionContext
  ): Promise<Response> {
    const url = new URL(request.url);

    // Only cache GET and HEAD requests
    if (request.method !== "GET" && request.method !== "HEAD") {
      return fetch(`${env.ORIGIN_URL}${url.pathname}${url.search}`, request);
    }

    const cache = caches.default;
    // Look up request in the local edge cache
    let response = await cache.match(request);

    if (!response) {
      // Cache miss: forward request to the origin server
      const originUrl = `${env.ORIGIN_URL}${url.pathname}${url.search}`;
      const originResponse = await fetch(originUrl, {
        headers: request.headers,
      });

      // Clone the response to modify headers and write to cache
      const newHeaders = new Headers(originResponse.headers);

      // Configure cache lifetime (s-maxage) and background refresh window
      newHeaders.set(
        "Cache-Control",
        "public, s-maxage=3600, stale-while-revalidate=60"
      );

      // Establish tag-based invalidation via Surrogate-Keys
      const tags = originResponse.headers.get("X-Cache-Tags") || "all-assets";
      newHeaders.set("Surrogate-Key", tags);

      response = new Response(originResponse.body, {
        status: originResponse.status,
        statusText: originResponse.statusText,
        headers: newHeaders,
      });

      // Cache response asynchronously to avoid blocking the client response
      ctx.waitUntil(cache.put(request, response.clone()));
    }

    return response;
  },
};

-- PHASE 1: EXPAND (Deploy new schema alongside old code)
-- Add a new column to store updated structures, leaving the old untouched
ALTER TABLE users ADD COLUMN phone_number_v2 VARCHAR(20) DEFAULT NULL;

-- Sync writes from both old and new code using a trigger
CREATE OR REPLACE FUNCTION sync_phone_numbers()
RETURNS TRIGGER AS $$
BEGIN
  IF NEW.phone_number IS NOT NULL AND NEW.phone_number_v2 IS NULL THEN
    NEW.phone_number_v2 := NEW.phone_number;
  ELSIF NEW.phone_number_v2 IS NOT NULL AND NEW.phone_number IS NULL THEN
    NEW.phone_number := NEW.phone_number_v2;
  END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER trg_sync_phone
BEFORE INSERT OR UPDATE ON users
FOR EACH ROW EXECUTE FUNCTION sync_phone_numbers();

-- PHASE 2: MIGRATE (Data backfill in the background)
-- Run in small batches to prevent database locking
-- UPDATE users SET phone_number_v2 = phone_number 
-- WHERE phone_number_v2 IS NULL AND phone_number IS NOT NULL;

-- PHASE 3: CONTRACT (Clean up old schema elements after full deployment)
DROP TRIGGER IF EXISTS trg_sync_phone ON users;
DROP FUNCTION IF EXISTS sync_phone_numbers;
ALTER TABLE users DROP COLUMN phone_number;
ALTER TABLE users RENAME COLUMN phone_number_v2 TO phone_number;

