You can prevent false sharing by ensuring that independent variables accessed by different threads are allocated on separate cache lines.

In C++11 and later, you can use the `alignas` specifier to align variables to cache line boundaries:

```cpp
struct OptimizedData {
    alignas(64) uint64_t thread1_count;
    alignas(64) uint64_t thread2_count;
};
```

This instructs the compiler to insert padding bytes so that each variable starts on a new 64-byte boundary, isolating them on separate cache lines. While this uses slightly more memory, it eliminates false sharing and prevents invalidation loops.

---

codeExamples.code:
#include <iostream>
#include <thread>
#include <vector>
#include <chrono>
#include <new>

const uint64_t ITERATIONS = 100000000ULL;

// Structure demonstrating False Sharing
// Adjacent members share the same 64-byte cache line
struct NaiveData {
    uint64_t thread1_count;
    uint64_t thread2_count;
} naive_data;

// Structure utilizing alignment attributes to isolate members on separate cache lines
struct OptimizedData {
    alignas(64) uint64_t thread1_count;
    alignas(64) uint64_t thread2_count;
} optimized_data;

void run_naive_worker1() {
    for (volatile uint64_t i = 0; i < ITERATIONS; ++i) {
        naive_data.thread1_count++;
    }
}

void run_naive_worker2() {
    for (volatile uint64_t i = 0; i < ITERATIONS; ++i) {
        naive_data.thread2_count++;
    }
}

void run_optimized_worker1() {
    for (volatile uint64_t i = 0; i < ITERATIONS; ++i) {
        optimized_data.thread1_count++;
    }
}

void run_optimized_worker2() {
    for (volatile uint64_t i = 0; i < ITERATIONS; ++i) {
        optimized_data.thread2_count++;
    }
}

int main() {
    std::cout << "Cache line size suggestion: " << std::hardware_destructive_interference_size << " bytes\n";
    std::cout << "Size of NaiveData: " << sizeof(NaiveData) << " bytes\n";
    std::cout << "Size of OptimizedData: " << sizeof(OptimizedData) << " bytes\n\n";

    // Test Naive execution (False Sharing)
    auto start_naive = std::chrono::high_resolution_clock::now();
    std::thread t1(run_naive_worker1);
    std::thread t2(run_naive_worker2);
    t1.join();
    t2.join();
    auto end_naive = std::chrono::high_resolution_clock::now();
    std::chrono::duration<double, std::milli> naive_duration = end_naive - start_naive;
    std::cout << "Naive execution time: " << naive_duration.count() << " ms\n";

    // Test Optimized execution (Aligned data boundaries)
    auto start_opt = std::chrono::high_resolution_clock::now();
    std::thread t3(run_optimized_worker1);
    std::thread t4(run_optimized_worker2);
    t3.join();
    t4.join();
    auto end_opt = std::chrono::high_resolution_clock::now();
    std::chrono::duration<double, std::milli> opt_duration = end_opt - start_opt;
    std::cout << "Optimized execution time: " << opt_duration.count() << " ms\n";

    double speedup = naive_duration.count() / opt_duration.count();
    std::cout << "Speedup achieved: " << speedup << "x\n";

    return 0;
}

package main

import (
    "bytes"
    "encoding/json"
    "fmt"
    "time"
)

// User represents a structured domain record.
type User struct {
    Name string `json:"name"`
    Age  int32  `json:"age"`
}

// EncodeVarint encodes an unsigned integer into a Protobuf-style Varint.
// It uses the most significant bit (MSB) as a continuation flag.
func EncodeVarint(value uint64) []byte {
    var buf []byte
    for {
        b := byte(value & 0x7F)
        value >>= 7
        if value != 0 {
            buf = append(buf, b|0x80)
        } else {
            buf = append(buf, b)
            break
        }
    }
    return buf
}

// DecodeVarint decodes a Varint from a byte slice.
// It returns the decoded value and the number of bytes consumed.
func DecodeVarint(buf []byte) (uint64, int) {
    var value uint64
    var shift uint
    for i, b := range buf {
        value |= uint64(b&0x7F) << shift
        if (b & 0x80) == 0 {
            return value, i + 1
        }
        shift += 7
    }
    return 0, 0
}

// EncodeProtobufManual serializes a User struct to the exact Protobuf wire format.
// Field 1 (Name): Wire Type 2 (length-delimited) -> Key: (1 << 3) | 2 = 10 (0x0A)
// Field 2 (Age): Wire Type 0 (varint) -> Key: (2 << 3) | 0 = 16 (0x10)
func EncodeProtobufManual(u *User) []byte {
    var buf bytes.Buffer

    // Field 1: Name (length-delimited string)
    nameBytes := []byte(u.Name)
    buf.WriteByte(10) // Field Key 10
    buf.Write(EncodeVarint(uint64(len(nameBytes))))
    buf.Write(nameBytes)

    // Field 2: Age (varint integer)
    buf.WriteByte(16) // Field Key 16
    buf.Write(EncodeVarint(uint64(u.Age)))

    return buf.Bytes()
}

// DecodeProtobufManual parses raw bytes back into a User struct.
func DecodeProtobufManual(data []byte) (*User, error) {
    u := &User{}
    i := 0
    for i < len(data) {
        key, bytesRead := DecodeVarint(data[i:])
        if bytesRead == 0 {
            return nil, fmt.Errorf("malformed key varint")
        }
        i += bytesRead

        fieldNum := key >> 3
        wireType := key & 7

        switch fieldNum {
        case 1:
            if wireType != 2 {
                return nil, fmt.Errorf("invalid wire type for Name: %d", wireType)
            }
            length, lenRead := DecodeVarint(data[i:])
            i += lenRead
            u.Name = string(data[i : i+int(length)])
            i += int(length)
        case 2:
            if wireType != 0 {
                return nil, fmt.Errorf("invalid wire type for Age: %d", wireType)
            }
            val, valRead := DecodeVarint(data[i:])
            i += valRead
            u.Age = int32(val)
        default:
            // Skip unknown fields (provides forward/backward compatibility)
            return nil, fmt.Errorf("unknown field encountered: %d", fieldNum)
        }
    }
    return u, nil
}

func main() {
    user := &User{Name: "Alice Smith", Age: 30}

    // 1. JSON Serialization
    jsonData, err := json.Marshal(user)
    if err != nil {
        panic(err)
    }
    var decodedJSON User
    _ = json.Unmarshal(jsonData, &decodedJSON)

    // 2. Manual Protobuf Serialization
    protoData := EncodeProtobufManual(user)
    decodedProto, err := DecodeProtobufManual(protoData)
    if err != nil {
        panic(err)
    }

    fmt.Printf("Source User: %+v\n\n", user)
    fmt.Printf("JSON output: %q (%d bytes)\n", string(jsonData), len(jsonData))
    fmt.Printf("Protobuf output: %v (%d bytes)\n\n", protoData, len(protoData))

    // Benchmark loop
    iterations := 100000

    start := time.Now()
    for i := 0; i < iterations; i++ {
        data, _ := json.Marshal(user)
        var u User
        _ = json.Unmarshal(data, &u)
    }
    jsonDuration := time.Since(start)

    start = time.Now()
    for i := 0; i < iterations; i++ {
        data := EncodeProtobufManual(user)
        _, _ = DecodeProtobufManual(data)
    }
    protoDuration := time.Since(start)

    fmt.Printf("Performance over %d runs:\n", iterations)
    fmt.Printf("JSON duration:     %v\n", jsonDuration)
    fmt.Printf("Protobuf duration: %v (%.2fx faster)\n", protoDuration, float64(jsonDuration)/float64(protoDuration))
}

package main

import (
	"fmt"
	"math/rand"
	"sort"
	"time"
)

// Row represents a physical database record
type Row struct {
	ID   int
	Data string
}

// BTreeIndex represents an ordered index (simulated via sorted slice for simplicity)
type BTreeIndex struct {
	keys []int
	rows []Row
}

// HashIndex represents an unordered index
type HashIndex struct {
	buckets map[int]Row
}

// Find performs an O(log N) point lookup in the B-Tree index using binary search
func (bt *BTreeIndex) Find(key int) (Row, bool, int) {
	steps := 0
	idx := sort.Search(len(bt.keys), func(i int) bool {
		steps++
		return bt.keys[i] >= key
	})
	if idx < len(bt.keys) && bt.keys[idx] == key {
		return bt.rows[idx], true, steps
	}
	return Row{}, false, steps
}

// FindRange performs a range scan in the B-Tree index
// It uses binary search to find the lower bound, then scans contiguous elements sequentially
func (bt *BTreeIndex) FindRange(minKey, maxKey int) ([]Row, int) {
	steps := 0
	idx := sort.Search(len(bt.keys), func(i int) bool {
		steps++
		return bt.keys[i] >= minKey
	})

	var results []Row
	for i := idx; i < len(bt.keys); i++ {
		steps++
		if bt.keys[i] > maxKey {
			break
		}
		results = append(results, bt.rows[i])
	}
	return results, steps
}

// Find performs an O(1) point lookup in the Hash index
func (h *HashIndex) Find(key int) (Row, bool, int) {
	row, exists := h.buckets[key]
	// Hash lookup is a constant time operation (1 step under ideal conditions)
	return row, exists, 1
}

// FindRange must perform a full scan of the Hash index because buckets are unsorted
func (h *HashIndex) FindRange(minKey, maxKey int) ([]Row, int) {
	var results []Row
	steps := 0
	// We must evaluate every bucket in the hash table
	for key, row := range h.buckets {
		steps++
		if key >= minKey && key <= maxKey {
			results = append(results, row)
		}
	}
	return results, steps
}

func main() {
	numRecords := 10000
	rand.Seed(time.Now().UnixNano())

	// Generate unique random keys
	keysMap := make(map[int]bool)
	var keys []int
	for len(keys) < numRecords {
		k := rand.Intn(100000)
		if !keysMap[k] {
			keysMap[k] = true
			keys = append(keys, k)
		}
	}

	// Initialize BTreeIndex (keys must be sorted)
	sort.Ints(keys)
	btree := &BTreeIndex{keys: keys, rows: make([]Row, numRecords)}
	hashIdx := &HashIndex{buckets: make(map[int]Row)}

	for i, k := range keys {
		row := Row{ID: k, Data: fmt.Sprintf("Data_%d", k)}
		btree.rows[i] = row
		hashIdx.buckets[k] = row
	}

	// Test Point Lookup
	targetKey := keys[numRecords/2]
	_, _, btSteps := btree.Find(targetKey)
	_, _, hashSteps := hashIdx.Find(targetKey)

	fmt.Printf("--- Point Lookup (Target Key: %d) ---\n", targetKey)
	fmt.Printf("B-Tree steps: %d (O(log N))\n", btSteps)
	fmt.Printf("Hash steps:   %d (O(1))\n\n", hashSteps)

	// Test Range Lookup
	minKey, maxKey := keys[numRecords/4], keys[numRecords/4+5] // Small range
	_, btRangeSteps := btree.FindRange(minKey, maxKey)
	_, hashRangeSteps := hashIdx.FindRange(minKey, maxKey)

	fmt.Printf("--- Range Query (Min: %d, Max: %d) ---\n", minKey, maxKey)
	fmt.Printf("B-Tree steps evaluated: %d (Seeks start, then scans sequentially)\n", btRangeSteps)
	fmt.Printf("Hash steps evaluated:   %d (Requires full table/bucket scan)\n", hashRangeSteps)
}

package main

import (
    "fmt"
    "sync"
    "time"
)

type WritePayload struct {
    Key   string
    Value string
}

type Hint struct {
    TargetNode string
    Payload    WritePayload
    Timestamp  time.Time
}

type Node struct {
    Name      string
    Reachable bool
    Data      map[string]string
    mu        sync.Mutex
}

func (n *Node) Write(key, val string) bool {
    n.mu.Lock()
    defer n.mu.Unlock()
    if !n.Reachable {
        return false
    }
    n.Data[key] = val
    return true
}

type Cluster struct {
    Nodes       []*Node
    N           int
    W           int
    R           int
    HintStorage map[string][]Hint
    mu          sync.Mutex
}

func NewCluster(nodeNames []string, w, r int) *Cluster {
    nodes := make([]*Node, len(nodeNames))
    for i, name := range nodeNames {
        nodes[i] = &Node{
            Name:      name,
            Reachable: true,
            Data:      make(map[string]string),
        }
    }
    return &Cluster{
        Nodes:       nodes,
        N:           len(nodeNames),
        W:           w,
        R:           r,
        HintStorage: make(map[string][]Hint),
    }
}

func (c *Cluster) Write(key, val string) error {
    payload := WritePayload{Key: key, Value: val}
    var wg sync.WaitGroup
    confirmations := 0
    var confMu sync.Mutex

    for _, node := range c.Nodes {
        wg.Add(1)
        go func(n *Node) {
            defer wg.Done()
            if success := n.Write(key, val); success {
                confMu.Lock()
                confirmations++
                confMu.Unlock()
            }
        }(node)
    }
    wg.Wait()

    if confirmations >= c.W {
        fmt.Printf("Strict write quorum met: %d/%d confirmations\n", confirmations, c.W)
        return nil
    }

    fmt.Printf("Strict write quorum failed (%d/%d). Attempting Sloppy Quorum...\n", confirmations, c.W)

    activeWrites := confirmations
    for _, node := range c.Nodes {
        if activeWrites >= c.W {
            break
        }

        node.mu.Lock()
        isReachable := node.Reachable
        node.mu.Unlock()

        if !isReachable {
            for _, backupNode := range c.Nodes {
                if backupNode.Name == node.Name {
                    continue
                }
                backupNode.mu.Lock()
                backupReachable := backupNode.Reachable
                backupNode.mu.Unlock()

                if backupReachable {
                    c.mu.Lock()
                    c.HintStorage[backupNode.Name] = append(c.HintStorage[backupNode.Name], Hint{
                        TargetNode: node.Name,
                        Payload:    payload,
                        Timestamp:  time.Now(),
                    })
                    c.mu.Unlock()

                    fmt.Printf("Stored hint on backup node %s for target offline node %s\n", backupNode.Name, node.Name)
                    activeWrites++
                    break
                }
            }
        }
    }

    if activeWrites >= c.W {
        fmt.Printf("Sloppy write quorum met: %d/%d confirmations (including hints)\n", activeWrites, c.W)
        return nil
    }

    return fmt.Errorf("write failed: failed to satisfy sloppy quorum (%d/%d)", activeWrites, c.W)
}

func (c *Cluster) RecoverNode(nodeName string) {
    var targetNode *Node
    for _, node := range c.Nodes {
        if node.Name == nodeName {
            targetNode = node
            break
        }
    }
    if targetNode == nil {
        return
    }

    targetNode.mu.Lock()
    targetNode.Reachable = true
    targetNode.mu.Unlock()
    fmt.Printf("Node %s has recovered and is online\n", nodeName)

    c.mu.Lock()
    defer c.mu.Unlock()

    for backupName, hints := range c.HintStorage {
        var activeHints []Hint
        for _, hint := range hints {
            if hint.TargetNode == nodeName {
                success := targetNode.Write(hint.Payload.Key, hint.Payload.Value)
                if success {
                    fmt.Printf("Replayed hint from %s to %s for key: %s\n", backupName, nodeName, hint.Payload.Key)
                } else {
                    activeHints = append(activeHints, hint)
                }
            } else {
                activeHints = append(activeHints, hint)
            }
        }
        c.HintStorage[backupName] = activeHints
    }
}

package main

import (
    "context"
    "fmt"
    "sync"
)

type Row struct {
    ID    int
    Value string
    Age   int
}

type ShardConnection interface {
    Query(ctx context.Context, sql string, args ...interface{}) ([]Row, error)
    Exec(ctx context.Context, sql string, args ...interface{}) error
}

type MockShard struct {
    ID   int
    Data []Row
}

func (m *MockShard) Query(ctx context.Context, sql string, args ...interface{}) ([]Row, error) {
    var minAge, maxAge int
    fmt.Sscanf(sql, "SELECT * FROM users WHERE age BETWEEN %d AND %d", &minAge, &maxAge)

    var res []Row
    for _, row := range m.Data {
        if row.Age >= minAge && row.Age <= maxAge {
            res = append(res, row)
        }
    }
    return res, nil
}

func (m *MockShard) Exec(ctx context.Context, sql string, args ...interface{}) error {
    row := args[0].(Row)
    m.Data = append(m.Data, row)
    return nil
}

type Router struct {
    mu          sync.RWMutex
    Shards      map[int]ShardConnection
    IsMigrating bool
    NewShards   map[int]ShardConnection
}

func (r *Router) ResolveShardsForRange(minAge, maxAge int) []int {
    var shardIDs []int
    if minAge <= 30 {
        shardIDs = append(shardIDs, 0)
    }
    if minAge <= 60 && maxAge >= 31 {
        shardIDs = append(shardIDs, 1)
    }
    if maxAge >= 61 {
        shardIDs = append(shardIDs, 2)
    }
    return shardIDs
}

func (r *Router) ScatterGatherQuery(ctx context.Context, minAge, maxAge int) ([]Row, error) {
    shardIDs := r.ResolveShardsForRange(minAge, maxAge)

    r.mu.RLock()
    defer r.mu.RUnlock()

    var wg sync.WaitGroup
    resultChan := make(chan []Row, len(shardIDs))
    errChan := make(chan error, len(shardIDs))

    sql := fmt.Sprintf("SELECT * FROM users WHERE age BETWEEN %d AND %d", minAge, maxAge)

    for _, shardID := range shardIDs {
        wg.Add(1)
        go func(id int) {
            defer wg.Done()
            shard, exists := r.Shards[id]
            if !exists {
                errChan <- fmt.Errorf("shard %d not configured", id)
                return
            }
            rows, err := shard.Query(ctx, sql)
            if err != nil {
                errChan <- err
                return
            }
            resultChan <- rows
        }(shardID)
    }

    wg.Wait()
    close(resultChan)
    close(errChan)

    if len(errChan) > 0 {
        return nil, <-errChan
    }

    var allRows []Row
    for rows := range resultChan {
        allRows = append(allRows, rows...)
    }

    return allRows, nil
}

func (r *Router) Write(ctx context.Context, shardKey int, row Row) error {
    r.mu.RLock()
    defer r.mu.RUnlock()

    shardID := shardKey % len(r.Shards)
    shard, exists := r.Shards[shardID]
    if !exists {
        return fmt.Errorf("target shard %d not found", shardID)
    }

    err := shard.Exec(ctx, "INSERT INTO users (id, value, age) VALUES ($1, $2, $3)", row)
    if err != nil {
        return err
    }

    if r.IsMigrating {
        newShardID := shardKey % len(r.NewShards)
        if newShard, exists := r.NewShards[newShardID]; exists {
            go func() {
                _ = newShard.Exec(ctx, "INSERT INTO users (id, value, age) VALUES ($1, $2, $3)", row)
            }()
        }
    }

    return nil
}

package main

import (
    "encoding/json"
    "fmt"
    "time"
)

type Resource struct {
    Name     string `json:"name"`
    Replicas int    `json:"replicas"`
    Image    string `json:"image"`
}

// MockGitRepository simulates a remote Git store holding desired state
func FetchDesiredStateFromGit() ([]byte, error) {
    desired := []Resource{
        {Name: "web-server", Replicas: 3, Image: "nginx:1.25"},
        {Name: "db-proxy", Replicas: 2, Image: "envoy:1.28"},
    }
    return json.Marshal(desired)
}

// MockK8sCluster simulates the live Kubernetes cluster state
type MockK8sCluster struct {
    LiveState map[string]*Resource
}

func (c *MockK8sCluster) FetchLiveState() map[string]*Resource {
    return c.LiveState
}

func (c *MockK8sCluster) ApplyChange(r Resource) {
    fmt.Printf("[K8s Cluster] Appying resource update: %s (Replicas: %d, Image: %s)\n", r.Name, r.Replicas, r.Image)
    c.LiveState[r.Name] = &r
}

func (c *MockK8sCluster) DeleteResource(name string) {
    fmt.Printf("[K8s Cluster] Deleting resource: %s\n", name)
    delete(c.LiveState, name)
}

// Reconcile compares desired Git state against live cluster resources
func Reconcile(cluster *MockK8sCluster) {
    desiredBytes, _ := FetchDesiredStateFromGit()
    var desiredState []Resource
    json.Unmarshal(desiredBytes, &desiredState)

    liveState := cluster.FetchLiveState()
    desiredMap := make(map[string]*Resource)

    // 1. Identify updates or missing resources
    for _, res := range desiredState {
        desiredMap[res.Name] = &res
        live, exists := liveState[res.Name]
        if !exists {
            fmt.Printf("[Reconciler] DRIFT DETECTED: Missing resource %s\n", res.Name)
            cluster.ApplyChange(res)
        } else if live.Replicas != res.Replicas || live.Image != res.Image {
            fmt.Printf("[Reconciler] DRIFT DETECTED: Resource %s mismatch. Live: {Replicas: %d, Image: %s}, Desired: {Replicas: %d, Image: %s}\n", 
                res.Name, live.Replicas, live.Image, res.Replicas, res.Image)
            cluster.ApplyChange(res)
        }
    }

    // 2. Identify orphaned resources (present in live cluster but deleted from Git)
    for name := range liveState {
        if _, exists := desiredMap[name]; !exists {
            fmt.Printf("[Reconciler] DRIFT DETECTED: Orphaned resource %s found in cluster but missing from Git\n", name)
            cluster.DeleteResource(name)
        }
    }
}

func main() {
    // Initialize live cluster with an out-of-sync database proxy and a manual override
    cluster := &MockK8sCluster{
        LiveState: map[string]*Resource{
            "web-server":      {Name: "web-server", Replicas: 3, Image: "nginx:1.25"},
            "db-proxy":        {Name: "db-proxy", Replicas: 1, Image: "envoy:1.25"}, // drift replicas & image
