import (
	"crypto/tls"
	"fmt"
	"io"
	"log"
	"net/http"

	"github.com/quic-go/quic-go"
	"github.com/quic-go/quic-go/http3"
)

func main() {
	// Configure TLS certificate with HTTP/3 ALPN parameter
	tlsConfig := &tls.Config{
		NextProtos: []string{"h3"},
	}

	mux := http.NewServeMux()
	mux.HandleFunc("/stream-data", func(w http.ResponseWriter, r *http.Request) {
		// Log connection migration info by checking remote address
		log.Printf("Received request from client %s using %s", r.RemoteAddr, r.Proto)

		// Access the underlying QUIC connection metadata if using quic-go context
		// This shows how we track Connection IDs across IP handoffs
		if conn, ok := r.Context().Value(http3.ServerContextKey).(quic.Connection); ok {
			log.Printf("QUIC Connection ID: %s", conn.RemoteAddr().String())
		}

		// Advertise HTTP/3 support via Alternative Services header
		w.Header().Set("Alt-Svc", `h3=":443"; max=2592000`)
		w.Header().Set("Content-Type", "application/octet-stream")

		// Leverage HTTP/2 & HTTP/3 stream flushing to stream binary frames
		flusher, ok := w.(http.Flusher)
		if !ok {
			http.Error(w, "Streaming not supported", http.StatusInternalServerError)
			return
		}

		for i := 1; i <= 5; i++ {
			payload := fmt.Sprintf("Frame-%d: Payload data over isolated QUIC stream\n", i)
			_, err := io.WriteString(w, payload)
			if err != nil {
				return
			}
			flusher.Flush() // Pushes the chunk immediately without waiting
		}
	})

	server := http3.Server{
		Addr:      ":443",
		Handler:   mux,
		TLSConfig: tlsConfig,
	}

	log.Printf("Starting HTTP/3 (QUIC) multiplexed server on UDP port :443...")
	// ListenAndServeTLS launches the server over UDP
	err := server.ListenAndServeTLS("server.crt", "server.key")
	if err != nil {
		log.Fatalf("Server exited with error: %v", err)
	}
}

package main

import (
    "crypto/rand"
    "crypto/rsa"
    "crypto/tls"
    "crypto/x509"
    "crypto/x509/pkix"
    "encoding/pem"
    "fmt"
    "log"
    "math/big"
    "net"
    "net/http"
    "time"
)

func main() {
    // Generate a 2048-bit RSA private key
    priv, err := rsa.GenerateKey(rand.Reader, 2048)
    if err != nil {
        log.Fatalf("Failed to generate private key: %v", err)
    }

    // Set up the X.509 certificate template
    notBefore := time.Now()
    notAfter := notBefore.Add(365 * 24 * time.Hour) // 1 year validity

    serialNumberLimit := new(big.Int).Lsh(big.NewInt(1), 128)
    serialNumber, err := rand.Int(rand.Reader, serialNumberLimit)
    if err != nil {
        log.Fatalf("Failed to generate serial number: %v", err)
    }

    template := x509.Certificate{
        SerialNumber: serialNumber,
        Subject: pkix.Name{
            Organization: []string{"Graphy Learning Platform"},
            CommonName:   "localhost",
        },
        NotBefore:             notBefore,
        NotAfter:              notAfter,
        KeyUsage:              x509.KeyUsageKeyEncipherment | x509.KeyUsageDigitalSignature,
        ExtKeyUsage:           []x509.ExtKeyUsage{x509.ExtKeyUsageServerAuth},
        BasicConstraintsValid: true,
        IPAddresses:           []net.IP{net.ParseIP("127.0.0.1")},
        DNSNames:              []string{"localhost"},
    }

    // Self-sign the certificate using the template and private key
    derBytes, err := x509.CreateCertificate(rand.Reader, &template, &template, &priv.PublicKey, priv)
    if err != nil {
        log.Fatalf("Failed to create certificate: %v", err)
    }

    // PEM-encode the certificate and private key
    certPEM := pem.EncodeToMemory(&pem.Block{Type: "CERTIFICATE", Bytes: derBytes})

    privBytes, err := x509.MarshalPKCS8PrivateKey(priv)
    if err != nil {
        log.Fatalf("Failed to marshal private key: %v", err)
    }
    keyPEM := pem.EncodeToMemory(&pem.Block{Type: "PRIVATE KEY", Bytes: privBytes})

    // Load certificate and private key into tls.Certificate
    cert, err := tls.X509KeyPair(certPEM, keyPEM)
    if err != nil {
        log.Fatalf("Failed to load X509 key pair: %v", err)
    }

    // Configure TLS settings
    tlsConfig := &tls.Config{
        Certificates: []tls.Certificate{cert},
        MinVersion:   tls.VersionTLS13,
    }

    // Create HTTP handler
    mux := http.NewServeMux()
    mux.HandleFunc("/", func(w http.ResponseWriter, r *http.Request) {
        w.Header().Set("Content-Type", "text/plain")
        fmt.Fprintf(w, "Hello, secure world! Served over HTTPS.\n")
    })

    // Create TCP listener and wrap in TLS
    listener, err := net.Listen("tcp", "127.0.0.1:8443")
    if err != nil {
        log.Fatalf("Failed to listen: %v", err)
    }
    tlsListener := tls.NewListener(listener, tlsConfig)
    defer tlsListener.Close()

    log.Println("HTTPS server starting on https://127.0.0.1:8443")
    server := &http.Server{Handler: mux}
    if err := server.Serve(tlsListener); err != nil {
        log.Fatalf("Server failed: %v", err)
    }
}

func CreatePayment(w http.ResponseWriter, r *http.Request) {
    key := r.Header.Get("Idempotency-Key")
    if key == "" {
        http.Error(w, "missing idempotency key", 400)
        return
    }

    // Check if we've seen this key before
    if result, ok := cache.Get(key); ok {
        json.NewEncoder(w).Encode(result)
        return
    }

    // Process the payment
    payment, err := processPayment(r)
    if err != nil {
        http.Error(w, err.Error(), 500)
        return
    }

    // Store result for future retries
    cache.Set(key, payment, 24*time.Hour)
    json.NewEncoder(w).Encode(payment)
}

