package main

import (
	"fmt"
	"net"
)

// SubnetDetails stores the computed properties of a CIDR block
type SubnetDetails struct {
	IP               net.IP
	SubnetMask       net.IPMask
	NetworkAddress   net.IP
	BroadcastAddress net.IP
	TotalHosts       uint32
	UsableHosts      uint32
	FirstUsableIP    net.IP
	LastUsableIP     net.IP
}

// calculateSubnet performs bitwise operations on IP representations
func calculateSubnet(cidrStr string) (*SubnetDetails, error) {
	// Parse CIDR string (e.g. "192.168.1.85/26")
	ip, ipNet, err := net.ParseCIDR(cidrStr)
	if err != nil {
		return nil, err
	}

	// Convert IP to 4-byte representation
	ip4 := ip.To4()
	if ip4 == nil {
		return nil, fmt.Errorf("calculator supports IPv4 only")
	}

	mask := ipNet.Mask
	network := ip4.Mask(mask) // Bitwise AND operation: isolates Network ID

	// Compute Broadcast Address: Network Address OR NOT Subnet Mask
	broadcast := make(net.IP, 4)
	for i := 0; i < 4; i++ {
		broadcast[i] = network[i] | ^mask[i]
	}

	// Calculate host capacities (2^(32 - prefixLength))
	ones, bits := mask.Size()
	hostBits := uint32(bits - ones)
	totalHosts := uint32(1) << hostBits
	var usableHosts uint32 = 0
	if totalHosts > 2 {
		usableHosts = totalHosts - 2 // Exclude network and broadcast addresses
	}

	// First usable IP: Network Address + 1
	firstUsable := make(net.IP, 4)
	copy(firstUsable, network)
	firstUsable[3]++

	// Last usable IP: Broadcast Address - 1
	lastUsable := make(net.IP, 4)
	copy(lastUsable, broadcast)
	lastUsable[3]--

	return &SubnetDetails{
		IP:               ip4,
		SubnetMask:       mask,
		NetworkAddress:   network,
		BroadcastAddress: broadcast,
		TotalHosts:       totalHosts,
		UsableHosts:      usableHosts,
		FirstUsableIP:    firstUsable,
		LastUsableIP:     lastUsable,
	}, nil
}

func main() {
	cidr := "192.168.1.85/26"
	details, err := calculateSubnet(cidr)
	if err != nil {
		fmt.Printf("Error: %v\n", err)
		return
	}

	fmt.Printf("CIDR Target: %s\n", cidr)
	fmt.Printf("Parsed IP Address: %v\n", details.IP)
	fmt.Printf("Subnet Mask (Hex): %v\n", details.SubnetMask)
	fmt.Printf("Network Address:   %v\n", details.NetworkAddress)
	fmt.Printf("Broadcast Address: %v\n", details.BroadcastAddress)
	fmt.Printf("Total IP Addresses: %d\n", details.TotalHosts)
	fmt.Printf("Usable Host Count:  %d\n", details.UsableHosts)
	fmt.Printf("Usable Host Range:  %v - %v\n", details.FirstUsableIP, details.LastUsableIP)
}

package main

import (
    "fmt"
    "os"
    "os/exec"
    "syscall"
)

// Run this code on a Linux host (or in a VM).
// Execute with: go run main.go run <command> <args>
func main() {
    if len(os.Args) < 2 {
        fmt.Println("Usage: go run main.go run [command] [args...]")
        os.Exit(1)
    }

    switch os.Args[1] {
    case "run":
        runParent()
    case "child":
        runChild()
    default:
        fmt.Printf("Unknown command: %s\n", os.Args[1])
        os.Exit(1)
    }
}

func runParent() {
    fmt.Printf("Running parent process (PID: %d)\n", os.Getpid())

    // Re-execute this binary as a child process, specifying the "child" argument
    cmd := exec.Command("/proc/self/exe", append([]string{"child"}, os.Args[2:]...)...)
    cmd.Stdin = os.Stdin
    cmd.Stdout = os.Stdout
    cmd.Stderr = os.Stderr

    // Configure namespace isolation flags
    cmd.SysProcAttr = &syscall.SysProcAttr{
        Cloneflags: syscall.CLONE_NEWUTS | // New hostnames namespace
            syscall.CLONE_NEWPID | // New process ID space (child will be PID 1)
            syscall.CLONE_NEWNS |  // New mount namespace
            syscall.CLONE_NEWNET,  // New isolated loopback network
    }

    if err := cmd.Run(); err != nil {
        fmt.Printf("Error running child process: %v\n", err)
        os.Exit(1)
    }
}

func runChild() {
    fmt.Printf("Running child container sandbox (PID: %d)\n", os.Getpid())

    // 1. Set hostname inside the isolated UTS namespace
    if err := syscall.Sethostname([]byte("container-sandbox")); err != nil {
        fmt.Printf("Failed to set hostname: %v\n", err)
    }

    // 2. Isolate the mount namespace: mount a private /proc filesystem
    // This ensures commands like `ps` only see processes in this container
    if err := syscall.Mount("proc", "/proc", "proc", 0, ""); err != nil {
        fmt.Printf("Failed to mount /proc: %v\n", err)
    }

    // 3. Execute the target program (e.g. /bin/sh)
    userCmd := os.Args[2]
    userArgs := os.Args[3:]

    cmd := exec.Command(userCmd, userArgs...)
    cmd.Stdin = os.Stdin
    cmd.Stdout = os.Stdout
    cmd.Stderr = os.Stderr

    if err := cmd.Run(); err != nil {
        fmt.Printf("Error executing user command: %v\n", err)
    }

    // Unmount proc before exiting to clean up
    syscall.Unmount("/proc", 0)
}

package main

import (
    "context"
    "log"
    "net/http"
    "net/http/httputil"
    "net/url"
    "sync"
    "sync/atomic"
    "time"
)

type Backend struct {
    URL          *url.URL
    Alive        bool
    mux          sync.RWMutex
    ReverseProxy *httputil.ReverseProxy
}

func (b *Backend) SetAlive(alive bool) {
    b.mux.Lock()
    b.Alive = alive
    b.mux.Unlock()
}

func (b *Backend) IsAlive() bool {
    b.mux.RLock()
    defer b.mux.RUnlock()
    return b.Alive
}

type ServerPool struct {
    backends []*Backend
    current  uint64
}

func (s *ServerPool) AddBackend(backend *Backend) {
    s.backends = append(s.backends, backend)
}

func (s *ServerPool) NextIndex() int {
    return int(atomic.AddUint64(&s.current, 1) % uint64(len(s.backends)))
}

func (s *ServerPool) GetNextPeer() *Backend {
    n := len(s.backends)
    for i := 0; i < n; i++ {
        idx := s.NextIndex()
        if s.backends[idx].IsAlive() {
            return s.backends[idx]
        }
    }
    return nil
}

func (s *ServerPool) HealthCheck() {
    for _, b := range s.backends {
        status := b.isAlive()
        b.SetAlive(status)
        if !status {
            log.Printf("Backend %s is DOWN", b.URL.String())
        }
    }
}

func (b *Backend) isAlive() bool {
    client := http.Client{
        Timeout: 2 * time.Second,
    }
    resp, err := client.Get(b.URL.String() + "/health")
    if err != nil {
        return false
    }
    defer resp.Body.Close()
    return resp.StatusCode == http.StatusOK
}

func main() {
    serverPool := &ServerPool{}

    targets := []string{
        "http://localhost:8081",
        "http://localhost:8082",
        "http://localhost:8083",
    }

    for _, target := range targets {
        targetURL, _ := url.Parse(target)
        proxy := httputil.NewSingleHostReverseProxy(targetURL)

        backend := &Backend{
            URL:          targetURL,
            Alive:        true,
            ReverseProxy: proxy,
        }
        serverPool.AddBackend(backend)
    }

    go func() {
        ticker := time.NewTicker(10 * time.Second)
        for range ticker.C {
            serverPool.HealthCheck()
        }
    }()

    frontendHandler := func(w http.ResponseWriter, r *http.Request) {
        peer := serverPool.GetNextPeer()
        if peer != nil {
            peer.ReverseProxy.ServeHTTP(w, r)
            return
        }
        http.Error(w, "Service Unavailable", http.StatusServiceUnavailable)
    }

    server := http.Server{
        Addr:    ":8080",
        Handler: http.HandlerFunc(frontendHandler),
    }

    log.Fatal(server.ListenAndServe())
}

package main

import (
    "fmt"
    "io"
    "net"
    "os"
    "syscall"
)

// ZeroCopyStreamer demonstrates streaming file segments directly to a TCP socket
// using the sendfile system call, bypassing user-space memory buffers.
type ZeroCopyStreamer struct {
    logFile *os.File
}

func NewZeroCopyStreamer(path string) (*ZeroCopyStreamer, error) {
    file, err := os.Open(path)
    if err != nil {
        return nil, err
    }
    return &ZeroCopyStreamer{logFile: file}, nil
}

// StreamSegment reads a chunk of the commit log from offset and writes it directly to conn
func (zs *ZeroCopyStreamer) StreamSegment(conn net.Conn, offset int64, length int64) (int64, error) {
    // In standard Go, if conn is a TCP connection and zs.logFile is a local file,
    // io.Copy or conn.ReadFrom will automatically optimize down to the sendfile system call
    // on Linux and Darwin.
    // To explicitly show system call mechanics, we can extract the raw file descriptors:

    tcpConn, ok := conn.(*net.TCPConn)
    if !ok {
        // Fallback to standard user-space copy if not a TCP connection
        fmt.Println("Fallback: copying via user space")
        _, err := zs.logFile.Seek(offset, io.SeekStart)
        if err != nil {
            return 0, err
        }
        return io.CopyN(conn, zs.logFile, length)
    }

    connVal, err := tcpConn.File()
    if err != nil {
        return 0, err
    }
    defer connVal.Close()

    dstFd := int(connVal.Fd())
    srcFd := int(zs.logFile.Fd())

    // Trigger Syscall sendfile(dstFd, srcFd, offset, length)
    // On macOS/Darwin, the system call is different (uses transfer flags), but Linux sendfile
    // is standard for system-level networking. Below we use the syscall package.
    // Note: syscall.Sendfile is OS-specific; on macOS, we simulate/wrap or use standard io.Copy
    // which compiles cross-platform.

    var written int
    off := offset

    // Using a cross-platform compilation safety fallback
    written, err = syscall.Sendfile(dstFd, srcFd, &off, int(length))
    if err != nil {
        return 0, err
    }

    return int64(written), nil
}

func main() {
    // Minimal execution demonstration
    fmt.Println("Zero-copy commit log reader configured.")
}

#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/mman.h>
#include <sys/stat.h>

int main(int argc, char *argv[]) {
    if (argc < 3) {
        fprintf(stderr, "Usage: %s <filename> <search_string>\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    const char *filename = argv[1];
    const char *search_str = argv[2];
    size_t search_len = strlen(search_str);

    int fd = open(filename, O_RDONLY);
    if (fd == -1) { perror("open"); exit(EXIT_FAILURE); }

    struct stat sb;
    if (fstat(fd, &sb) == -1) { perror("fstat"); close(fd); exit(EXIT_FAILURE); }
    size_t file_size = sb.st_size;

    if (file_size == 0) {
        printf("File is empty.\n");
        close(fd);
        return 0;
    }

    // Map the file into the process's virtual memory address space
    char *mapped_data = mmap(NULL, file_size, PROT_READ, MAP_SHARED, fd, 0);
    if (mapped_data == MAP_FAILED) {
        perror("mmap"); close(fd); exit(EXIT_FAILURE);
    }

    // Declare advice to guide the kernel's read-ahead paging engine
    madvise(mapped_data, file_size, MADV_SEQUENTIAL);
    madvise(mapped_data, file_size, MADV_WILLNEED);

    // Perform in-memory search across mapped data pointer offsets
    size_t match_count = 0;
    for (size_t i = 0; i <= file_size - search_len; i++) {
        if (memcmp(&mapped_data[i], search_str, search_len) == 0) {
            match_count++;
            printf("Match found at offset %zu\n", i);
        }
    }

    printf("Total matches: %zu\n", match_count);

    // Clean up resources
    if (munmap(mapped_data, file_size) == -1) { perror("munmap"); }
    close(fd);
    return 0;
}

