import (
    "context"
    "errors"
    "fmt"
    "net/http"
    "net/http/httptest"
    "time"
)

// InventoryService defines the contract for checking item availability
type InventoryService interface {
    CheckStock(itemID string) (int, error)
}

// MonolithInventory represents the monolithic approach: in-memory struct access
type MonolithInventory struct{}

func (m *MonolithInventory) CheckStock(itemID string) (int, error) {
    // Microsecond read from local cache or direct function call
    if itemID == "item_123" {
        return 5, nil
    }
    return 0, errors.New("item not found")
}

// MicroserviceInventory represents the decentralized approach: HTTP network RPC
type MicroserviceInventory struct {
    BaseURL string
    Client  *http.Client
}

func (ms *MicroserviceInventory) CheckStock(ctx context.Context, itemID string) (int, error) {
    reqURL := fmt.Sprintf("%s/stock?id=%s", ms.BaseURL, itemID)

    req, err := http.NewRequestWithContext(ctx, "GET", reqURL, nil)
    if err != nil {
        return 0, err
    }

    // Network request with timeout boundaries
    resp, err := ms.Client.Do(req)
    if err != nil {
        return 0, fmt.Errorf("network error (timeout/outage): %w", err)
    }
    defer resp.Body.Close()

    if resp.StatusCode != http.StatusOK {
        return 0, fmt.Errorf("remote service returned status: %d", resp.StatusCode)
    }

    // Simulate decoding JSON body
    return 5, nil
}

func main() {
    // --- 1. MONOLITHIC MODEL: Direct In-Memory Call ---
    monolith := &MonolithInventory{}
    start := time.Now()
    stock, err := monolith.CheckStock("item_123")
    duration := time.Since(start)

    fmt.Printf("[Monolith] In-memory check completed in %v. Stock: %d (Err: %v)\n", duration, stock, err)

    // --- 2. MICROSERVICES MODEL: Network call to separate process ---
    mockServer := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
        // Simulate minor network delay
        time.Sleep(5 * time.Millisecond)
        w.WriteHeader(http.StatusOK)
        w.Write([]byte(`{"stock": 5}`))
    }))
    defer mockServer.Close()

    msClient := &MicroserviceInventory{
        BaseURL: mockServer.URL,
        Client: &http.Client{
            Timeout: 10 * time.Millisecond,
        },
    }

    ctx, cancel := context.WithTimeout(context.Background(), 20*time.Millisecond)
    defer cancel()

    start = time.Now()
    msStock, msErr := msClient.CheckStock(ctx, "item_123")
    duration = time.Since(start)

    fmt.Printf("[Microservices] Network RPC completed in %v. Stock: %d (Err: %v)\n", duration, msStock, msErr)
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <sys/epoll.h>

#define MAX_EVENTS 64
#define PORT 8080
#define BUFFER_SIZE 1024

/* Set socket descriptor to non-blocking mode */
int make_socket_non_blocking(int sfd) {
    int flags = fcntl(sfd, F_GETFL, 0);
    if (flags == -1) {
        perror("fcntl F_GETFL");
        return -1;
    }
    flags |= O_NONBLOCK;
    if (fcntl(sfd, F_SETFL, flags) == -1) {
        perror("fcntl F_SETFL");
        return -1;
    }
    return 0;
}

int main() {
    int listen_fd, epoll_fd;
    struct sockaddr_in address;
    int opt = 1;

    /* 1. Create a raw TCP socket */
    listen_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (listen_fd == -1) {
        perror("socket creation failed");
        exit(EXIT_FAILURE);
    }

    /* 2. Enable SO_REUSEADDR socket option to reuse port immediately */
    if (setsockopt(listen_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) == -1) {
        perror("setsockopt SO_REUSEADDR failed");
        close(listen_fd);
        exit(EXIT_FAILURE);
    }

    memset(&address, 0, sizeof(address));
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    /* 3. Bind socket to target address and port */
    if (bind(listen_fd, (struct sockaddr *)&address, sizeof(address)) == -1) {
        perror("bind failed");
        close(listen_fd);
        exit(EXIT_FAILURE);
    }

    /* 4. Configure socket as non-blocking */
    if (make_socket_non_blocking(listen_fd) == -1) {
        close(listen_fd);
        exit(EXIT_FAILURE);
    }

    /* 5. Listen for incoming connections (SYN backlog capacity: 128) */
    if (listen(listen_fd, 128) == -1) {
        perror("listen failed");
        close(listen_fd);
        exit(EXIT_FAILURE);
    }

    /* 6. Initialize epoll instance */
    epoll_fd = epoll_create1(0);
    if (epoll_fd == -1) {
        perror("epoll_create1 failed");
        close(listen_fd);
        exit(EXIT_FAILURE);
    }

    struct epoll_event event;
    struct epoll_event events[MAX_EVENTS];

    event.data.fd = listen_fd;
    event.events = EPOLLIN | EPOLLET; /* Edge-triggered read monitor */

    /* 7. Register listen socket with epoll */
    if (epoll_ctl(epoll_fd, EPOLL_CTL_ADD, listen_fd, &event) == -1) {
        perror("epoll_ctl add listen_fd failed");
        close(listen_fd);
        close(epoll_fd);
        exit(EXIT_FAILURE);
    }

    /* 8. Execute high-performance event loop */
    while (1) {
        int n = epoll_wait(epoll_fd, events, MAX_EVENTS, -1);
        for (int i = 0; i < n; i++) {
            if ((events[i].events & EPOLLERR) ||
                (events[i].events & EPOLLHUP) ||
                (!(events[i].events & EPOLLIN))) {
                /* Handle error or socket disconnection */
                fprintf(stderr, "epoll error on fd %d\n", events[i].data.fd);
                close(events[i].data.fd);
                continue;
            }

            if (listen_fd == events[i].data.fd) {
                /* Handle new incoming connection requests */
                while (1) {
                    struct sockaddr in_addr;
                    socklen_t in_len = sizeof(in_addr);
                    int infd = accept(listen_fd, &in_addr, &in_len);
                    if (infd == -1) {
                        if ((errno == EAGAIN) || (errno == EWOULDBLOCK)) {
                            /* All connections in backlog accepted */
                            break;
                        }
                        perror("accept failed");
                        break;
                    }

                    if (make_socket_non_blocking(infd) == -1) {
                        close(infd);
                        continue;
                    }

                    event.data.fd = infd;
                    event.events = EPOLLIN | EPOLLET; /* Edge-triggered read monitoring */
                    if (epoll_ctl(epoll_fd, EPOLL_CTL_ADD, infd, &event) == -1) {
                        perror("epoll_ctl add client fd failed");
                        close(infd);
                    }
                }
            } else {
                /* Process data ready to read on existing connection */
                int client_fd = events[i].data.fd;
                char buf[BUFFER_SIZE];
                int close_conn = 0;

                while (1) {
                    ssize_t count = read(client_fd, buf, sizeof(buf));
                    if (count == -1) {
                        if (errno != EAGAIN && errno != EWOULDBLOCK) {
                            perror("read error");
                            close_conn = 1;
                        }
                        break;
                    } else if (count == 0) {
                        /* EOF, client closed connection */
                        close_conn = 1;
                        break;
                    }

                    /* Echo the read bytes back to the client socket */
                    ssize_t written = write(client_fd, buf, count);
                    if (written == -1) {
                        perror("write error");
                        close_conn = 1;
                        break;
                    }
                }

                if (close_conn) {
                    close(client_fd);
                }
            }
        }
    }
    close(listen_fd);
    close(epoll_fd);
    return 0;
}

package main

import (
    "context"
    "net/http"
    "time"

    "github.com/prometheus/client_golang/prometheus"
    "github.com/prometheus/client_golang/prometheus/promauto"
    "go.opentelemetry.io/otel"
    "go.opentelemetry.io/otel/attribute"
    "go.opentelemetry.io/otel/propagation"
    "go.opentelemetry.io/otel/trace"
)

var (
    httpRequestsTotal = promauto.NewCounterVec(
        prometheus.CounterOpts{
            Name: "http_requests_total",
            Help: "Total number of HTTP requests processed.",
        },
        []string{"path", "status"},
    )
    httpRequestDuration = promauto.NewHistogramVec(
        prometheus.HistogramOpts{
            Name:    "http_request_duration_seconds",
            Help:    "Latency of HTTP requests in seconds.",
            Buckets: prometheus.DefBuckets,
        },
        []string{"path"},
    )
)

func traceMiddleware(next http.Handler) http.Handler {
    return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
        start := time.Now()

        // 1. Extract W3C traceparent header context from incoming call
        propagator := propagation.TraceContext{}
        ctx := propagator.Extract(r.Context(), propagation.HeaderCarrier(r.Header))

        // 2. Start a new span linked to the parent trace context
        tracer := otel.Tracer("http-server")
        ctx, span := tracer.Start(ctx, "ServeHTTP", trace.WithSpanKind(trace.SpanKindServer))
        defer span.End()

        span.SetAttributes(
            attribute.String("http.method", r.Method),
            attribute.String("http.path", r.URL.Path),
        )

        wrapped := &responseWriter{ResponseWriter: w, statusCode: http.StatusOK}
        next.ServeHTTP(wrapped, r.WithContext(ctx))

        // 3. Record metrics (latency histogram and request counters)
        duration := time.Since(start).Seconds()
        httpRequestDuration.WithLabelValues(r.URL.Path).Observe(duration)
        httpRequestsTotal.WithLabelValues(r.URL.Path, http.StatusText(wrapped.statusCode)).Inc()

        span.SetAttributes(attribute.Int("http.status_code", wrapped.statusCode))
    })
}

func callDownstreamService(ctx context.Context, url string) error {
    // 4. Inject active trace context into outgoing HTTP request
    req, err := http.NewRequestWithContext(ctx, "GET", url, nil)
    if err != nil {
        return err
    }

    propagator := propagation.TraceContext{}
    propagator.Inject(ctx, propagation.HeaderCarrier(req.Header))

    client := &http.Client{Timeout: 5 * time.Second}
    resp, err := client.Do(req)
    if err != nil {
        return err
    }
    defer resp.Body.Close()

    return nil
}

type responseWriter struct {
    http.ResponseWriter
    statusCode int
}

func (rw *responseWriter) WriteHeader(code int) {
    rw.statusCode = code
    rw.ResponseWriter.WriteHeader(code)
}

sections.content:
Cursor-based pagination enforces clean stateless REST standards by embedding state indicators inside server response bodies. 

Instead of forcing the client application to calculate offset numbers dynamically, the server generates the URL for the next page of data, encoding the last record's ID into the query string:

```json
{
  "data": [
    {"id": 90009, "name": "User_90009"},
    {"id": 90010, "name": "User_90010"}
  ],
  "paging": {
    "next": "/api/users?limit=10&cursor=90010"
  }
}
```

This self-describing response model isolates pagination execution details on the server. If the cursor structure changes later (e.g. switching from integer IDs to encrypted tokens), client code remains unchanged.

---

codeExamples.code:
package main

import (
    "fmt"
    "time"
)

// Record represents a simplified database row structure.
type Record struct {
    ID   int
    Name string
}

// QueryPlan describes how the database planner processes a select request.
type QueryPlan struct {
    Query        string
    ScanType     string
    RowsScanned  int
    RowsReturned int
}

type DatabaseSimulator struct {
    records []Record
}

// NewDatabaseSimulator initializes a simulated database table with a size.
func NewDatabaseSimulator(size int) *DatabaseSimulator {
    records := make([]Record, size)
    for i := 0; i < size; i++ {
        records[i] = Record{
            ID:   i + 1,
            Name: fmt.Sprintf("User_%d", i+1),
        }
    }
    return &DatabaseSimulator{records: records}
}

// QueryOffset simulates: SELECT * FROM users LIMIT 10 OFFSET 90000
func (db *DatabaseSimulator) QueryOffset(limit, offset int) ([]Record, QueryPlan, time.Duration) {
    start := time.Now()

    // Simulated Table Scan: loops through items sequentially to discard OFFSET rows.
    scanned := 0
    result := []Record{}

    for i := 0; i < len(db.records); i++ {
        scanned++
        if scanned > offset {
            result = append(result, db.records[i])
            if len(result) == limit {
                break
            }
        }
    }

    duration := time.Since(start)

    plan := QueryPlan{
        Query:        fmt.Sprintf("SELECT * FROM users LIMIT %d OFFSET %d", limit, offset),
        ScanType:     "SEQUENTIAL INDEX LEAF SCAN (O(N))",
        RowsScanned:  scanned,
        RowsReturned: len(result),
    }

    return result, plan, duration
}

// QueryCursor simulates: SELECT * FROM users WHERE id > 90000 ORDER BY id LIMIT 10
func (db *DatabaseSimulator) QueryCursor(limit, lastSeenID int) ([]Record, QueryPlan, time.Duration) {
    start := time.Now()

    // Simulated B-Tree Index Seek: O(log N) operations to seek the node pointer,
    // then scans only the LIMIT contiguous leaf records.
    btreeLookupComparisons := 17 // log2(100000)
    scanned := btreeLookupComparisons

    result := []Record{}

    // Perform simulated binary search on primary key index
    low, high := 0, len(db.records)-1
    foundIdx := -1
    for low <= high {
        mid := (low + high) / 2
        if db.records[mid].ID == lastSeenID {
            foundIdx = mid
            break
        } else if db.records[mid].ID < lastSeenID {
            low = mid + 1
        } else {
            high = mid - 1
        }
    }

    if foundIdx != -1 {
        for i := foundIdx + 1; i < len(db.records); i++ {
            scanned++
            result = append(result, db.records[i])
            if len(result) == limit {
                break
            }
        }
    }

    duration := time.Since(start)

    plan := QueryPlan{
        Query:        fmt.Sprintf("SELECT * FROM users WHERE id > %d ORDER BY id LIMIT %d", lastSeenID, limit),
        ScanType:     "INDEX SEEK + LEAF SCAN (O(log N))",
        RowsScanned:  scanned,
        RowsReturned: len(result),
    }

    return result, plan, duration
}

// SimulatePageDrift illustrates data duplicate/skipped anomalies in Offset paging
func SimulatePageDrift() {
    fmt.Println("--- PAGE DRIFT CONCURRENT WRITE ANOMALY ---")

    // Initial db state
    records := []Record{
        {ID: 1, Name: "Alice"},
        {ID: 2, Name: "Bob"},
        {ID: 3, Name: "Charlie"},
        {ID: 4, Name: "David"},
        {ID: 5, Name: "Eve"},
    }

    // Client fetches Page 1 (limit 2, offset 0) -> Alice, Bob
    fmt.Println("Client fetches Page 1 (Offset: LIMIT 2 OFFSET 0):")
    for _, r := range records[0:2] {
        fmt.Printf("  -> %s\n", r.Name)
    }

    // Concurrent write inserts a row at position 0, shifting list items down
    fmt.Println("\n[Concurrent Event]: 'Zach' is inserted at the top!")
    shiftedRecords := []Record{
        {ID: 0, Name: "Zach"},
        {ID: 1, Name: "Alice"},
        {ID: 2, Name: "Bob"},
        {ID: 3, Name: "Charlie"},
        {ID: 4, Name: "David"},
        {ID: 5, Name: "Eve"},
    }

    // Client fetches Page 2 (limit 2, offset 2) -> Bob, Charlie (Bob is duplicate!)
    fmt.Println("Client fetches Page 2 (Offset: LIMIT 2 OFFSET 2):")
    for _, r := range shiftedRecords[2:4] {
        fmt.Printf("  -> %s\n", r.Name)
    }
    fmt.Println("Result: Bob was read twice! (Page Drift Anomaly)\n")

    // Cursor-based approach
    fmt.Println("Client fetches Page 1 (Cursor-based: LIMIT 2, initial query):")
    for _, r := range records[0:2] {
        fmt.Printf("  -> %s\n", r.Name)
    }
    lastSeenID := 2 // Last seen record is Bob (ID 2)

    // Client fetches Page 2 (WHERE ID > 2 LIMIT 2)
    fmt.Printf("Client fetches Page 2 (Cursor: WHERE id > %d LIMIT 2):\n", lastSeenID)
    count := 0
    for _, r := range shiftedRecords {
        if r.ID > lastSeenID {
            fmt.Printf("  -> %s\n", r.Name)
            count++
            if count == 2 {
                break
            }
        }
    }
    fmt.Println("Result: Reads Charlie and David correctly. No duplicates!")
}

func main() {
    db := NewDatabaseSimulator(100000)

    // 1. Run Offset query at deep offset (row 90,000)
    offsetLimit := 10
    offsetValue := 90000
    _, planOffset, timeOffset := db.QueryOffset(offsetLimit, offsetValue)

    // 2. Run Cursor query at same depth
    cursorLimit := 10
    lastSeenID := 90000
    _, planCursor, timeCursor := db.QueryCursor(cursorLimit, lastSeenID)

    fmt.Printf("OFFSET QUERY:\n  SQL: %s\n  Plan: %s\n  Scanned Rows: %d\n  Time: %v\n\n",
        planOffset.Query, planOffset.ScanType, planOffset.RowsScanned, timeOffset)

    fmt.Printf("CURSOR QUERY:\n  SQL: %s\n  Plan: %s\n  Scanned Rows: %d\n  Time: %v\n\n",
        planCursor.Query, planCursor.ScanType, planCursor.RowsScanned, timeCursor)

    SimulatePageDrift()
}

