package main

import (
	"io"
	"log"
	"net"
	"net/http"
	"net/http/httputil"
	"net/url"
)

// ==========================================
// 1. RAW TCP FORWARD PROXY IMPLEMENTATION
// ==========================================
// tcpForwardProxy listens locally and pipes raw bytes to a target server.
// Used by clients inside a private network to reach external targets.
func startTCPForwardProxy(localPort, targetAddr string) {
	listener, err := net.Listen("tcp", ":"+localPort)
	if err != nil {
		log.Fatalf("Forward Proxy failed to listen: %v", err)
	}
	defer listener.Close()

	log.Printf("TCP Forward Proxy listening on :%s, forwarding to %s\n", localPort, targetAddr)

	for {
		clientConn, err := listener.Accept()
		if err != nil {
			log.Printf("Failed to accept client connection: %v", err)
			continue
		}

		// Connect to the external target server on behalf of the client
		targetConn, err := net.Dial("tcp", targetAddr)
		if err != nil {
			log.Printf("Failed to connect to target server: %v", err)
			clientConn.Close()
			continue
		}

		// Splice connections: copy data bi-directionally in background routines
		go func(c, t net.Conn) {
			defer c.Close()
			defer t.Close()
			io.Copy(t, c) // Pipe client request to target
		}(clientConn, targetConn)

		go func(c, t net.Conn) {
			defer c.Close()
			defer t.Close()
			io.Copy(c, t) // Pipe target response to client
		}(clientConn, targetConn)
	}
}

// ==========================================
// 2. HTTP REVERSE PROXY WITH HEADER INJECTION
// ==========================================
// startReverseProxy runs an HTTP reverse proxy acting as ingress for backend microservices.
func startReverseProxy(listenPort, targetURLStr string) {
	target, err := url.Parse(targetURLStr)
	if err != nil {
		log.Fatalf("Invalid backend URL: %v", err)
	}

	// Create standard library reverse proxy utility
	proxy := httputil.NewSingleHostReverseProxy(target)

	// Modify default director to inject upstream tracking headers
	originalDirector := proxy.Director
	proxy.Director = func(req *http.Request) {
		originalDirector(req)

		// Extract client IP address from network connection
		clientIP, _, err := net.SplitHostPort(req.RemoteAddr)
		if err == nil {
			// Append Client IP to X-Forwarded-For header chain
			existingXFF := req.Header.Get("X-Forwarded-For")
			if existingXFF != "" {
				req.Header.Set("X-Forwarded-For", existingXFF+", "+clientIP)
			} else {
				req.Header.Set("X-Forwarded-For", clientIP)
			}

			// Set standard X-Real-IP header to track direct ingress connection
			req.Header.Set("X-Real-IP", clientIP)
		}

		// Inject authentication or tracing tokens dynamically
		req.Header.Set("X-Proxy-Ingress", "ReverseProxy-Go-Gateway")
	}

	log.Printf("HTTP Reverse Proxy listening on :%s, ingress for %s\n", listenPort, targetURLStr)
	log.Fatal(http.ListenAndServe(":"+listenPort, proxy))
}

func main() {
	// Run raw TCP Forward Proxy in background (e.g. forward local port 8080 to a web target)
	go startTCPForwardProxy("8080", "127.0.0.1:9090")

	// Run HTTP Reverse Proxy synchronously (e.g. gateway on 8000 sending to target service 9090)
	startReverseProxy("8000", "http://127.0.0.1:9090")
}

import * as http from 'http';
import * as crypto from 'crypto';

// ==========================================
// 1. STATEFUL SESSION ENGINE IMPLEMENTATION
// ==========================================
interface Session {
  userId: string;
  expiresAt: number;
}

class StatefulSessionServer {
  // In-memory session store (simulates Redis or a SQL database table)
  private sessionStore = new Map<string, Session>();
  private sessionExpiryMs = 15 * 60 * 1000; // 15 minutes

  public handleRequest(req: http.IncomingMessage, res: http.ServerResponse): void {
    const url = req.url || '';

    if (url === '/login' && req.method === 'POST') {
      // Simulate user authentication success
      const userId = 'user_98765';
      const sessionId = crypto.randomBytes(32).toString('hex');
      const expiresAt = Date.now() + this.sessionExpiryMs;

      // Store session in database/cache
      this.sessionStore.set(sessionId, { userId, expiresAt });

      // Send session ID back in a secure, HttpOnly cookie
      res.writeHead(200, {
        'Set-Cookie': `SID=${sessionId}; HttpOnly; Secure; SameSite=Strict; Path=/`,
        'Content-Type': 'application/json'
      });
      res.end(JSON.stringify({ success: true, message: 'Logged in successfully' }));
      return;
    }

    if (url === '/profile' && req.method === 'GET') {
      const cookies = this.parseCookies(req.headers.cookie);
      const sessionId = cookies['SID'];

      if (!sessionId) {
        res.writeHead(401, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ error: 'Unauthorized: No session cookie' }));
        return;
      }

      // Stateful verification: must hit the memory store/database
      const session = this.sessionStore.get(sessionId);
      if (!session) {
        res.writeHead(401, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ error: 'Unauthorized: Session not found' }));
        return;
      }

      if (Date.now() > session.expiresAt) {
        this.sessionStore.delete(sessionId);
        res.writeHead(401, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ error: 'Unauthorized: Session expired' }));
        return;
      }

      res.writeHead(200, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ userId: session.userId, model: 'stateful-session' }));
      return;
    }

    if (url === '/logout' && req.method === 'POST') {
      const cookies = this.parseCookies(req.headers.cookie);
      const sessionId = cookies['SID'];

      if (sessionId) {
        // Immediate revocation: delete state from store
        this.sessionStore.delete(sessionId);
      }

      res.writeHead(200, {
        'Set-Cookie': 'SID=; HttpOnly; Secure; SameSite=Strict; Path=/; Max-Age=0',
        'Content-Type': 'application/json'
      });
      res.end(JSON.stringify({ success: true, message: 'Logged out' }));
      return;
    }

    res.writeHead(404);
    res.end();
  }

  private parseCookies(cookieHeader?: string): Record<string, string> {
    const list: Record<string, string> = {};
    if (!cookieHeader) return list;
    cookieHeader.split(';').forEach((cookie) => {
      const parts = cookie.split('=');
      list[parts.shift()!.trim()] = decodeURI(parts.join('='));
    });
    return list;
  }
}

// ==========================================
// 2. STATELESS JWT TOKEN ENGINE IMPLEMENTATION
// ==========================================
class StatelessTokenServer {
  // Generate asymmetric RSA keys for token signing and verification
  private privateKey: string;
  private publicKey: string;

  constructor() {
    const { privateKey, publicKey } = crypto.generateKeyPairSync('rsa', {
      modulusLength: 2048,
      publicKeyEncoding: { type: 'spki', format: 'pem' },
      privateKeyEncoding: { type: 'pkcs8', format: 'pem' }
    });
    this.privateKey = privateKey;
    this.publicKey = publicKey;
  }

  public handleRequest(req: http.IncomingMessage, res: http.ServerResponse): void {
    const url = req.url || '';

    if (url === '/login' && req.method === 'POST') {
      const userId = 'user_98765';

      // Create JWT header and payload
      const header = JSON.stringify({ alg: 'RS256', typ: 'JWT' });
      const payload = JSON.stringify({
        sub: userId,
        exp: Math.floor(Date.now() / 1000) + 15 * 60 // 15 minutes
      });

      // Base64Url encode parts
      const encodedHeader = this.base64UrlEncode(Buffer.from(header));
      const encodedPayload = this.base64UrlEncode(Buffer.from(payload));

      // Cryptographic signing with private key
      const signer = crypto.createSign('RSA-SHA256');
      signer.update(`${encodedHeader}.${encodedPayload}`);
      const signature = signer.sign(this.privateKey);
      const encodedSignature = this.base64UrlEncode(signature);

      const jwt = `${encodedHeader}.${encodedPayload}.${encodedSignature}`;

      res.writeHead(200, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ token: jwt }));
      return;
    }

    if (url === '/profile' && req.method === 'GET') {
      const authHeader = req.headers.authorization;
      if (!authHeader || !authHeader.startsWith('Bearer ')) {
        res.writeHead(401, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ error: 'Unauthorized: Missing Bearer token' }));
        return;
      }

      const token = authHeader.split(' ')[1];
      const parts = token.split('.');
      if (parts.length !== 3) {
        res.writeHead(400, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ error: 'Bad Request: Invalid token format' }));
        return;
      }

      const [headerB64, payloadB64, signatureB64] = parts;

      // Stateless verification: decrypt/verify signature using public key (no DB read)
      const verifier = crypto.createVerify('RSA-SHA256');
      verifier.update(`${headerB64}.${payloadB64}`);

      const isVerified = verifier.verify(
        this.publicKey,
        Buffer.from(signatureB64, 'base64url')
      );

      if (!isVerified) {
        res.writeHead(401, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ error: 'Unauthorized: Invalid token signature' }));
        return;
      }

      // Decode payload and verify expiration
      const payload = JSON.parse(Buffer.from(payloadB64, 'base64url').toString('utf8'));
      if (Math.floor(Date.now() / 1000) > payload.exp) {
        res.writeHead(401, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ error: 'Unauthorized: Token expired' }));
        return;
      }

      res.writeHead(200, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ userId: payload.sub, model: 'stateless-token' }));
      return;
    }

    if (url === '/logout' && req.method === 'POST') {
      // Note: Since this server is stateless, we cannot revoke the token immediately.
      // We can only instruct the client to discard it.
      res.writeHead(200, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({
        success: true,
        message: 'Token discarded by client, but it remains cryptographically valid until expiration.'
      }));
      return;
    }

    res.writeHead(404);
    res.end();
  }

  private base64UrlEncode(buf: Buffer): string {
    return buf.toString('base64')
      .replace(/=/g, '')
      .replace(/\+/g, '-')
      .replace(/\//g, '_');
  }
}

// Startup code simulation
const sessionServer = new StatefulSessionServer();
const tokenServer = new StatelessTokenServer();

http.createServer((req, res) => {
  if (req.url?.startsWith('/session')) {
    req.url = req.url.replace('/session', '');
    sessionServer.handleRequest(req, res);
  } else {
    req.url = req.url?.replace('/token', '');
    tokenServer.handleRequest(req, res);
  }
}).listen(8080, () => {
  console.log('Authentication servers running on port 8080');
});

package main

import (
	"fmt"
	"time"
)

// Record represents a single row in our database
type Record struct {
	ID     uint32
	Age    uint32
	Salary uint32
}

// RowStore stores records as a contiguous slice of structs
type RowStore struct {
	data []Record
}

// ColumnStore stores fields in separate contiguous slices
type ColumnStore struct {
	ids      []uint32
	ages     []uint32
	salaries []uint32
	size     int
}

// AverageSalaryRow calculates the average salary using RowStore
// This requires reading the entire struct slice, loading unnecessary fields (ID, Age) into cache
func (rs *RowStore) AverageSalaryRow() (uint32, int) {
	var sum uint64
	bytesRead := 0
	for i := 0; i < len(rs.data); i++ {
		sum += uint64(rs.data[i].Salary)
		// Each struct is 12 bytes: ID (4 bytes) + Age (4 bytes) + Salary (4 bytes)
		bytesRead += 12
	}
	return uint32(sum / uint64(len(rs.data))), bytesRead
}

// AverageSalaryCol calculates the average salary using ColumnStore
// This only scans the salaries array, utilizing the CPU cache efficiently
func (cs *ColumnStore) AverageSalaryCol() (uint32, int) {
	var sum uint64
	bytesRead := 0
	for i := 0; i < cs.size; i++ {
		sum += uint64(cs.salaries[i])
		// Only the Salary slice is read: 4 bytes per record
		bytesRead += 4
	}
	return uint32(sum / uint64(cs.size)), bytesRead
}

func main() {
	numRecords := 5000000
	fmt.Printf("Initializing stores with %d records...\n", numRecords)

	// Allocate memory
	rowData := make([]Record, numRecords)
	colIds := make([]uint32, numRecords)
	colAges := make([]uint32, numRecords)
	colSalaries := make([]uint32, numRecords)

	for i := 0; i < numRecords; i++ {
		val := uint32(i % 100)
		rowData[i] = Record{ID: uint32(i), Age: val, Salary: 50000 + val*100}

		colIds[i] = uint32(i)
		colAges[i] = val
		colSalaries[i] = 50000 + val*100
	}

	rowStore := &RowStore{data: rowData}
	colStore := &ColumnStore{ids: colIds, ages: colAges, salaries: colSalaries, size: numRecords}

	// Benchmark Row-Oriented Scan
	start := time.Now()
	avgRow, bytesRow := rowStore.AverageSalaryRow()
	durationRow := time.Since(start)

	// Benchmark Column-Oriented Scan
	start = time.Now()
	avgCol, bytesCol := colStore.AverageSalaryCol()
	durationCol := time.Since(start)

	fmt.Printf("\n--- Results ---\n")
	fmt.Printf("Row Store:   Average Salary = %d, Duration = %v, Bytes Scanned = %d MB\n", avgRow, durationRow, bytesRow/(1024*1024))
	fmt.Printf("Column Store: Average Salary = %d, Duration = %v, Bytes Scanned = %d MB\n", avgCol, durationCol, bytesCol/(1024*1024))
}

package main

import (
    "crypto/tls"
    "crypto/x509"
    "fmt"
    "log"
    "net"
    "time"
)

func main() {
    address := "cloudflare.com:443"
    dialer := &net.Dialer{ Timeout: 5 * time.Second }

    // Establish a raw TCP connection
    conn, err := dialer.Dial("tcp", address)
    if (err != nil) {
        log.Fatalf("Failed to establish TCP socket: %v", err)
    }
    defer conn.Close()

    // Configure TLS settings, enforcing TLS 1.3 and ALPN HTTP/2
    config := &tls.Config{
        MinVersion: tls.VersionTLS13,
        MaxVersion: tls.VersionTLS13,
        NextProtos: []string{"h2", "http/1.1"},
        ServerName: "cloudflare.com",
    }

    // Wrap the raw network connection inside a secure TLS client context
    tlsConn := tls.Client(conn, config)

    // Initiate the cryptographic handshake
    err = tlsConn.Handshake()
    if (err != nil) {
        log.Fatalf("TLS Handshake failure: %v", err)
    }

    state := tlsConn.ConnectionState()
    fmt.Printf("Connection established: %s\n", address)
    fmt.Printf("Negotiated Protocol: %s\n", state.NegotiatedProtocol)
    fmt.Printf("TLS Version: 0x%X\n", state.Version)
    fmt.Printf("Cipher Suite: %s\n\n", tls.CipherSuiteName(state.CipherSuite))

    // Inspect the server certificate chain
    fmt.Println("Server Certificate Chain:")
    for i, cert := range state.PeerCertificates {
        fmt.Printf("[%d] Subject: %s\n", i, cert.Subject.CommonName)
        fmt.Printf("    Issuer:  %s\n", cert.Issuer.CommonName)
        fmt.Printf("    Expires: %s\n", cert.NotAfter.Format(time.RFC3339))

        // Verify certificate cryptographic validity
        _, err := cert.Verify(x509.VerifyOptions{
            DNSName: "cloudflare.com",
            Roots:   nil, // System root stores used when nil
        })
        if (err != nil) {
            fmt.Printf("    Verification: FAILED (%v)\n", err)
        } else {
            fmt.Println("    Verification: VALID")
        }
    }
}

#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/socket.h>
#include <sys/epoll.h>
#include <netinet/in.h>
#include <fcntl.h>
#include <unistd.h>
#include <errno.h>

#define MAX_EVENTS 64
#define PORT 8080
#define BUFFER_SIZE 512

int make_socket_non_blocking(int sfd) {
    int flags = fcntl(sfd, F_GETFL, 0);
    if (flags == -1) return -1;
    flags |= O_NONBLOCK;
    if (fcntl(sfd, F_SETFL, flags) == -1) return -1;
    return 0;
}

int main() {
    int sfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sfd == -1) { perror("socket"); exit(EXIT_FAILURE); }

    int opt = 1;
    setsockopt(sfd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt));

    struct sockaddr_in address;
    memset(&address, 0, sizeof(address));
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    if (bind(sfd, (struct sockaddr *)&address, sizeof(address)) == -1) {
        perror("bind"); exit(EXIT_FAILURE);
    }

    if (make_socket_non_blocking(sfd) == -1) {
        perror("non-blocking"); exit(EXIT_FAILURE);
    }

    if (listen(sfd, SOMAXCONN) == -1) {
        perror("listen"); exit(EXIT_FAILURE);
    }

    int epfd = epoll_create1(0);
    if (epfd == -1) { perror("epoll_create1"); exit(EXIT_FAILURE); }

    struct epoll_event event;
    event.data.fd = sfd;
    event.events = EPOLLIN | EPOLLET; // Edge-Triggered
    if (epoll_ctl(epfd, EPOLL_CTL_ADD, sfd, &event) == -1) {
        perror("epoll_ctl"); exit(EXIT_FAILURE);
    }

    struct epoll_event events[MAX_EVENTS];
    printf("Server listening on port %d...\n", PORT);

    while (1) {
        int n = epoll_wait(epfd, events, MAX_EVENTS, -1);
        for (int i = 0; i < n; i++) {
            if ((events[i].events & EPOLLERR) || (events[i].events & EPOLLHUP) || (!(events[i].events & EPOLLIN))) {
                fprintf(stderr, "epoll error on fd %d\n", events[i].data.fd);
                close(events[i].data.fd);
                continue;
            }

            if (events[i].data.fd == sfd) {
                // Accept loop for incoming connections (ET requires loop until EAGAIN)
                while (1) {
                    struct sockaddr in_addr;
                    socklen_t in_len = sizeof(in_addr);
                    int infd = accept(sfd, &in_addr, &in_len);
                    if (infd == -1) {
                        if ((errno == EAGAIN) || (errno == EWOULDBLOCK)) {
                            break; // Processed all pending connections
                        } else {
                            perror("accept"); break;
                        }
                    }
                    if (make_socket_non_blocking(infd) == -1) {
                        close(infd); break;
                    }
                    event.data.fd = infd;
                    event.events = EPOLLIN | EPOLLET | EPOLLRDHUP;
                    if (epoll_ctl(epfd, EPOLL_CTL_ADD, infd, &event) == -1) {
                        perror("epoll_ctl_add"); close(infd);
                    }
                }
            } else {
                // Handle data from client
                int done = 0;
                int client_fd = events[i].data.fd;
                while (1) {
                    char buf[BUFFER_SIZE];
                    ssize_t count = read(client_fd, buf, sizeof(buf));
                    if (count == -1) {
                        if (errno != EAGAIN) {
                            perror("read error"); done = 1;
                        }
                        break; // EAGAIN means no more data to read for now
                    } else if (count == 0) {
                        done = 1; // End of file (client closed connection)
                        break;
                    }
                    // Process received data bytes
                    write(STDOUT_FILENO, buf, count);
                }
                if (done) {
                    printf("Closed connection on descriptor %d\n", client_fd);
                    close(client_fd);
                }
            }
        }
    }
    close(sfd);
    return 0;
